//go:build linux
// +build linux

// Code generated by gen-gdrcopy from gdrapi.h. DO NOT EDIT.

package gdrcopy

import (
	"errors"
	"runtime"
	"sync"
	"syscall"
	"unsafe"
)

// GPUPageShift, GPUPageSize and GPUPageMask are the GPU page granularity the
// kernel module pins at, from GPU_PAGE_SHIFT in gdrapi.h. PinBuffer aligns the
// address it is given down to this boundary and rounds the length up, so a
// pinning generally begins below the address requested. GetInfoV2 reports
// where it actually begins.
const (
	GPUPageShift = 16
	GPUPageSize  = uintptr(1) << GPUPageShift
	GPUPageMask  = ^(GPUPageSize - 1)
)

// HeaderVersionMajor and HeaderVersionMinor are GDR_API_MAJOR_VERSION and
// GDR_API_MINOR_VERSION from the header these bindings were generated from.
// They describe the header, not the library that ends up loaded:
// RuntimeGetVersion asks the library itself.
const (
	HeaderVersionMajor = 2
	HeaderVersionMinor = 6
)

// MinimumDriverVersionMajor and MinimumDriverVersionMinor are the oldest
// gdrdrv the pinned header supports, from MINIMUM_GDRDRV_VERSION.
// DriverGetVersion reports what is loaded.
const (
	MinimumDriverVersionMajor = 2
	MinimumDriverVersionMinor = 0
)

// MemHandle identifies one pinned GPU buffer. It is gdr_mh_t, which gdrapi.h
// declares as a struct wrapping a single unsigned long.
//
// The C struct is one integer word wide, and every ABI gdrcopy builds for
// (System V x86-64, AAPCS64, ELFv2 ppc64le) passes such a struct in one
// general-purpose register, exactly as it passes the bare word, so MemHandle
// is a scalar here rather than a Go struct. TestMemHandleABI checks the width
// against what a C compiler measured, and generation fails outright if
// gdr_mh_t ever grows a second member.
//
// The value is the address of an allocation inside libgdrapi. It means
// something only to the Handle that produced it, and libgdrapi frees and
// reuses the allocation after UnpinBuffer.
type MemHandle uint64

// Error reports a libgdrapi call that failed.
//
// gdrcopy has no status enum: its calls return POSIX error numbers directly,
// so errors.Is against a syscall.Errno works.
//
//	if errors.Is(err, syscall.EINVAL) { ... }
//
// One exception is worth knowing about. Under the dma-buf backend, which
// libgdrapi selects when gdrdrv is absent, a failing pin can return a CUDA
// driver result code rather than an errno. Err then holds that number and its
// message is meaningless; compare against the numeric value in that case.
type Error struct {
	// Op is the C entry point that failed, spelled as the library spells it.
	Op string
	// Err is the number the library returned.
	Err syscall.Errno
}

// Error describes the failing call and its error number.
func (e *Error) Error() string { return "gdrcopy: " + e.Op + ": " + e.Err.Error() }

// Unwrap returns the underlying error number.
func (e *Error) Unwrap() error { return e.Err }

// toError converts a libgdrapi return code to an error. Zero is success.
func toError(op string, rc int32) error {
	if rc == 0 {
		return nil
	}
	return &Error{Op: op, Err: syscall.Errno(rc)}
}

// ErrOpen reports that gdr_open returned NULL.
//
// gdr_open reports no error code. It needs either the gdrdrv kernel module
// loaded, or a CUDA driver whose device supports dma-buf mmap, and says
// neither which was missing nor why. Set GDRCOPY_ENABLE_LOGGING in the
// environment to make libgdrapi write its own diagnosis to stderr.
var ErrOpen = errors.New("gdrcopy: gdr_open failed: gdrdrv is not loaded and no visible device supports dma-buf mmap")

// ErrHandle and ErrMemHandle report a call on a zero handle. libgdrapi
// dereferences both a gdr_t and a gdr_mh_t without checking them, so a zero
// value would reach C as a null dereference. These are returned instead.
var (
	ErrHandle    = errors.New("gdrcopy: zero Handle")
	ErrMemHandle = errors.New("gdrcopy: zero MemHandle")
)

// ErrMapped reports an unpin or a close while a mapping this package created
// is still live. gdrapi.h requires gdr_unmap before gdr_unpin_buffer:
// unpinning first leaves the process holding an mmap of an aperture the driver
// has released.
var ErrMapped = errors.New("gdrcopy: mapping is still mapped; call Unmap first")

// ErrNotMapped reports an unmap or a copy on a handle this package has no live
// mapping for.
var ErrNotMapped = errors.New("gdrcopy: handle is not mapped")

// ErrUnmapRange reports an Unmap whose address or length differs from the Map
// that created the mapping. gdr_unmap rounds the length up to a host page and
// calls munmap on the result, so a wrong length unmaps memory the caller never
// mapped.
var ErrUnmapRange = errors.New("gdrcopy: Unmap address or size does not match the Map that created the mapping")

// ErrCopyRange reports a copy whose range falls outside the mapping.
var ErrCopyRange = errors.New("gdrcopy: copy range is outside the mapping")

// libgdrapi keeps each state object's pinned buffers on an unlocked linked
// list, and its own source says so: "GDRCopy is not thread-safe". Every call
// that mutates that list is serialized here under stateMu, so concurrent use
// through these bindings does not corrupt it. Copies do not touch the list and
// take the read lock only to bounds-check against the mapping.
//
// pins records what this package created, which is what lets Unmap, UnpinBuffer
// and Close check the release order gdrapi.h requires instead of trusting it.
// It knows nothing about a handle obtained some other way and converted to a
// Handle or a MemHandle.
var (
	stateMu sync.RWMutex
	pins    = map[MemHandle]*pinState{}
)

type pinState struct {
	g      Handle
	mapped bool
	va     uintptr
	size   uintptr
}

// Open opens libgdrapi's state object, connecting to the gdrdrv kernel module
// or, when gdrdrv is absent, to the CUDA driver's dma-buf mmap backend. Set
// GDRCOPY_USE_DMABUF_MMAP=1 in the environment to force the second.
//
// Close releases it. Close frees the state object inside the library, so a
// Handle used after Close, or closed twice, is a use-after-free. This package
// cannot detect that: the handle is an address the library hands back, and
// nothing in Go distinguishes a live one from a freed one.
func Open() (Handle, error) {
	if err := checkLibSym("gdr_open"); err != nil {
		return 0, err
	}
	stateMu.Lock()
	defer stateMu.Unlock()
	g := fnOpen()
	if g == 0 {
		return 0, ErrOpen
	}
	return g, nil
}

// Close releases the library state object.
//
// Every mapping made through this package must be released with Unmap first:
// Close returns ErrMapped and does nothing while any remains. Pinned buffers
// need not be unpinned first, because gdr_close unpins whatever is left, and
// this package then forgets them.
func (g Handle) Close() error {
	if g == 0 {
		return ErrHandle
	}
	stateMu.Lock()
	defer stateMu.Unlock()
	for _, p := range pins {
		if p.g == g && p.mapped {
			return ErrMapped
		}
	}
	if err := checkLibSym("gdr_close"); err != nil {
		return err
	}
	if err := toError("gdr_close", fnClose(g)); err != nil {
		return err
	}
	for mh, p := range pins {
		if p.g == g {
			delete(pins, mh)
		}
	}
	return nil
}

// PinBuffer pins size bytes of GPU memory at addr, a CUDA device address from
// cuMemAlloc or an equivalent, and returns a handle to the pinning.
//
// The kernel module aligns the pinning down to GPUPageSize and rounds the
// length up, so the pinned region generally starts below addr. GetInfoV2
// reports where it starts: the offset of the caller's data inside the mapping
// is addr - Info.Va, and Map returns the base of the mapping, not the address
// of that data.
//
// p2pToken and vaSpace are the peer-to-peer token arguments NVIDIA deprecated.
// Pass zero for both. libgdrapi ignores them unless the loaded gdrdrv predates
// its v2 pin ioctl, and PinBufferV2 drops them.
//
// Release with UnpinBuffer, after Unmap if the handle was mapped.
func (g Handle) PinBuffer(addr, size uintptr, p2pToken uint64, vaSpace uint32) (MemHandle, error) {
	return g.pin("gdr_pin_buffer", func(out *MemHandle) int32 {
		return fnPinBuffer(g, uint(addr), uint(size), p2pToken, vaSpace, out)
	})
}

// PinBufferV2 pins size bytes of GPU memory at addr with an explicit flag. It
// aligns the pinning exactly as PinBuffer does.
//
// PinFlagForcePcie asks for a GPU BAR1 mapping, which is supported only on
// certain coherent platforms, needs persistent mappings enabled, and needs
// both a GPU driver of release 570 or newer and a gdrdrv new enough to carry
// the flag. It fails with syscall.EINVAL otherwise. GetAttribute with
// AttrSupportPinFlagForcePcie reports whether the loaded pair supports it,
// though the header notes the pin itself can still fail on an unsupported
// platform.
//
// gdr_pin_buffer_v2 was added in gdrcopy 2.5. Against an older libgdrapi this
// returns *SymbolError; PinBuffer is exported by every 2.x release.
func (g Handle) PinBufferV2(addr, size uintptr, flags PinFlags) (MemHandle, error) {
	return g.pin("gdr_pin_buffer_v2", func(out *MemHandle) int32 {
		return fnPinBufferV2(g, uint(addr), uint(size), uint32(flags), out)
	})
}

func (g Handle) pin(op string, call func(*MemHandle) int32) (MemHandle, error) {
	if g == 0 {
		return 0, ErrHandle
	}
	if err := checkLibSym(op); err != nil {
		return 0, err
	}
	stateMu.Lock()
	defer stateMu.Unlock()
	var mh MemHandle
	if err := toError(op, call(&mh)); err != nil {
		return 0, err
	}
	if mh == 0 {
		return 0, errors.New("gdrcopy: " + op + " reported success and returned a zero handle")
	}
	pins[mh] = &pinState{g: g}
	return mh, nil
}

// UnpinBuffer releases the pinning.
//
// Any mapping of mh must be released with Unmap first, as gdrapi.h requires.
// UnpinBuffer returns ErrMapped and does nothing while a mapping this package
// created is still live.
func (g Handle) UnpinBuffer(mh MemHandle) error {
	if g == 0 {
		return ErrHandle
	}
	if mh == 0 {
		return ErrMemHandle
	}
	stateMu.Lock()
	defer stateMu.Unlock()
	if p, ok := pins[mh]; ok && p.mapped {
		return ErrMapped
	}
	if err := checkLibSym("gdr_unpin_buffer"); err != nil {
		return err
	}
	if err := toError("gdr_unpin_buffer", fnUnpinBuffer(g, mh)); err != nil {
		return err
	}
	delete(pins, mh)
	return nil
}

// Map creates a user-space mapping of the pinned buffer and returns its base
// address.
//
// The address is an mmap of a device aperture, not Go memory. Do not build a
// Go slice on it and do not load or store through it directly: neither the
// store width nor the ordering a Go access produces is what such a mapping
// requires. Use CopyToMapping and CopyFromMapping, which run libgdrapi's
// per-architecture uncached copy paths and issue the fences those paths need.
//
// size is remembered and must be passed back to Unmap unchanged. gdr_unmap
// rounds it up to a host page and calls munmap on the result, so a different
// size unmaps a different range.
//
// The mapping begins at the GPU-page-aligned base of the pinning. Add
// addr - Info.Va, from GetInfoV2, to reach the data that was pinned.
func (g Handle) Map(mh MemHandle, size uintptr) (uintptr, error) {
	return g.mapping("gdr_map", mh, size, func(out *uintptr) int32 {
		return fnMap(g, mh, out, uint(size))
	})
}

// MapV2 creates a user-space mapping and asks for a particular mapping type.
//
// MapFlagDefault lets the kernel module choose, which is what Map does.
// The other flags request a write-combining, cached, or device mapping, and
// fail with syscall.EINVAL when the loaded gdrdrv cannot provide the one
// asked for. Info.MappingType reports what was actually established.
//
// gdr_map_v2 was added in gdrcopy 2.5. Against an older libgdrapi this returns
// *SymbolError; Map is exported by every 2.x release.
func (g Handle) MapV2(mh MemHandle, size uintptr, flags MapFlags) (uintptr, error) {
	return g.mapping("gdr_map_v2", mh, size, func(out *uintptr) int32 {
		return fnMapV2(g, mh, out, uint(size), int32(flags))
	})
}

func (g Handle) mapping(op string, mh MemHandle, size uintptr, call func(*uintptr) int32) (uintptr, error) {
	if g == 0 {
		return 0, ErrHandle
	}
	if mh == 0 {
		return 0, ErrMemHandle
	}
	if err := checkLibSym(op); err != nil {
		return 0, err
	}
	stateMu.Lock()
	defer stateMu.Unlock()
	var va uintptr
	if err := toError(op, call(&va)); err != nil {
		return 0, err
	}
	p := pins[mh]
	if p == nil {
		p = &pinState{g: g}
		pins[mh] = p
	}
	p.mapped, p.va, p.size = true, va, size
	return va, nil
}

// Unmap releases the user-space mapping.
//
// va and size must be exactly what Map returned and was given. Unmap returns
// ErrUnmapRange without calling the library otherwise, because gdr_unmap
// passes the rounded-up length straight to munmap and would unmap a range the
// caller does not own.
func (g Handle) Unmap(mh MemHandle, va, size uintptr) error {
	if g == 0 {
		return ErrHandle
	}
	if mh == 0 {
		return ErrMemHandle
	}
	stateMu.Lock()
	defer stateMu.Unlock()
	p := pins[mh]
	if p == nil || !p.mapped {
		return ErrNotMapped
	}
	if p.va != va || p.size != size {
		return ErrUnmapRange
	}
	if err := checkLibSym("gdr_unmap"); err != nil {
		return err
	}
	if err := toError("gdr_unmap", fnUnmap(g, mh, va, uint(size))); err != nil {
		return err
	}
	p.mapped, p.va, p.size = false, 0, 0
	return nil
}

// GetInfoV2 reports where the driver pinned the buffer and how it is mapped.
//
// There is no GetInfo, and that is deliberate. gdrapi.h defines gdr_get_info
// as a macro expanding to gdr_get_info_v2, but libgdrapi still exports a
// symbol spelled gdr_get_info: the obsolete v1 entry point, which writes a
// struct eight bytes shorter with no mapping type. Binding that name and
// handing it an Info would leave MappingType unwritten and report success.
//
// gdr_get_info_v2 was added in gdrcopy 2.4. Against an older libgdrapi this
// returns *SymbolError.
func (g Handle) GetInfoV2(mh MemHandle) (Info, error) {
	var info Info
	if g == 0 {
		return info, ErrHandle
	}
	if mh == 0 {
		return info, ErrMemHandle
	}
	if err := checkLibSym("gdr_get_info_v2"); err != nil {
		return info, err
	}
	stateMu.RLock()
	defer stateMu.RUnlock()
	return info, toError("gdr_get_info_v2", fnGetInfoV2(g, mh, &info))
}

// GetCallbackFlag reports whether the GPU driver has run the invalidation
// callback for this pinning, which it does when the device memory is freed,
// by cuMemFree or process teardown, before UnpinBuffer. Once it has, the
// mapping no longer refers to the caller's buffer and reading through it is
// meaningless.
//
// Under the dma-buf backend there is no such callback and this always reports
// false.
func (g Handle) GetCallbackFlag(mh MemHandle) (bool, error) {
	if g == 0 {
		return false, ErrHandle
	}
	if mh == 0 {
		return false, ErrMemHandle
	}
	if err := checkLibSym("gdr_get_callback_flag"); err != nil {
		return false, err
	}
	stateMu.RLock()
	defer stateMu.RUnlock()
	var flag int32
	if err := toError("gdr_get_callback_flag", fnGetCallbackFlag(g, mh, &flag)); err != nil {
		return false, err
	}
	return flag != 0, nil
}

// GetAttribute reports a system-wide property of the GDRCopy installation.
// Per-handle properties come from GetInfoV2 instead.
//
// gdr_get_attribute was added in gdrcopy 2.5. Against an older libgdrapi this
// returns *SymbolError.
func (g Handle) GetAttribute(attr Attr) (int32, error) {
	if g == 0 {
		return 0, ErrHandle
	}
	if err := checkLibSym("gdr_get_attribute"); err != nil {
		return 0, err
	}
	stateMu.RLock()
	defer stateMu.RUnlock()
	var v int32
	if err := toError("gdr_get_attribute", fnGetAttribute(g, attr, &v)); err != nil {
		return 0, err
	}
	return v, nil
}

// DriverGetVersion reports the version of the loaded gdrdrv kernel module.
// MinimumDriverVersionMajor and MinimumDriverVersionMinor are the oldest the
// pinned header supports.
//
// Under the dma-buf backend there is no kernel module and the underlying ioctl
// fails.
func (g Handle) DriverGetVersion() (major, minor int32, err error) {
	if g == 0 {
		return 0, 0, ErrHandle
	}
	if err := checkLibSym("gdr_driver_get_version"); err != nil {
		return 0, 0, err
	}
	stateMu.RLock()
	defer stateMu.RUnlock()
	if err := toError("gdr_driver_get_version", fnDriverGetVersion(g, &major, &minor)); err != nil {
		return 0, 0, err
	}
	return major, minor, nil
}

// RuntimeGetVersion reports the version of the loaded libgdrapi, which is not
// necessarily the version of the header these bindings were generated from.
// See HeaderVersionMajor and HeaderVersionMinor for that.
func RuntimeGetVersion() (major, minor int32, err error) {
	if err := checkLibSym("gdr_runtime_get_version"); err != nil {
		return 0, 0, err
	}
	fnRuntimeGetVersion(&major, &minor)
	return major, minor, nil
}

// CopyToMapping copies src into the mapping at mapDPtr, which must lie inside
// the mapping Map returned for mh.
//
// The copy is synchronous and borrows src only for its duration. It runs
// libgdrapi's uncached store path and the fence that path requires, which is
// why a plain Go store into the mapping is not a substitute.
//
// The library does not order this copy against GPU work already launched, and
// does not promise that a partly completed copy is invisible to it. See the
// [GPUDirect RDMA sync behavior] notes for what is and is not guaranteed.
//
// [GPUDirect RDMA sync behavior]: https://docs.nvidia.com/cuda/gpudirect-rdma/index.html#sync-behavior
func (mh MemHandle) CopyToMapping(mapDPtr uintptr, src []byte) error {
	if err := mh.checkCopy("gdr_copy_to_mapping", mapDPtr, len(src)); err != nil {
		return err
	}
	if len(src) == 0 {
		return nil
	}
	err := toError("gdr_copy_to_mapping", fnCopyToMapping(mh, mapDPtr, unsafe.Pointer(&src[0]), uint(len(src))))
	runtime.KeepAlive(src)
	return err
}

// CopyFromMapping copies len(dst) bytes into dst from the mapping at mapDPtr,
// which must lie inside the mapping Map returned for mh. The same ordering
// caveats as CopyToMapping apply.
func (mh MemHandle) CopyFromMapping(dst []byte, mapDPtr uintptr) error {
	if err := mh.checkCopy("gdr_copy_from_mapping", mapDPtr, len(dst)); err != nil {
		return err
	}
	if len(dst) == 0 {
		return nil
	}
	err := toError("gdr_copy_from_mapping", fnCopyFromMapping(mh, unsafe.Pointer(&dst[0]), mapDPtr, uint(len(dst))))
	runtime.KeepAlive(dst)
	return err
}

// checkCopy rejects a copy the library would answer with a null dereference or
// a write outside the mapping. gdr_copy_to_mapping and gdr_copy_from_mapping
// take no gdr_t and check only that the handle is mapped; the range is the
// caller's responsibility, and getting it wrong writes over whatever the
// aperture is next to.
func (mh MemHandle) checkCopy(symbol string, mapDPtr uintptr, n int) error {
	if mh == 0 {
		return ErrMemHandle
	}
	stateMu.RLock()
	p := pins[mh]
	var mapped bool
	var va, size uintptr
	if p != nil {
		mapped, va, size = p.mapped, p.va, p.size
	}
	stateMu.RUnlock()
	if !mapped {
		return ErrNotMapped
	}
	if mapDPtr < va || mapDPtr > va+size || uintptr(n) > va+size-mapDPtr {
		return ErrCopyRange
	}
	return checkLibSym(symbol)
}

// MappingTypeString returns libgdrapi's own name for t. The library answers
// with a pointer to one of its static strings, which this copies.
//
// MappingType.String, generated from the header, gives the Go constant name
// and needs no library. Use it unless the library's spelling is what is wanted.
//
// gdr_get_mapping_type_string was added in gdrcopy 2.5. Against an older
// libgdrapi this returns *SymbolError.
func MappingTypeString(t MappingType) (string, error) {
	if err := checkLibSym("gdr_get_mapping_type_string"); err != nil {
		return "", err
	}
	var p *byte
	if err := toError("gdr_get_mapping_type_string", fnGetMappingTypeString(t, &p)); err != nil {
		return "", err
	}
	return goString(p), nil
}

// goString copies a NUL-terminated C string.
func goString(p *byte) string {
	if p == nil {
		return ""
	}
	n := 0
	for *(*byte)(unsafe.Add(unsafe.Pointer(p), n)) != 0 {
		n++
	}
	return string(unsafe.Slice(p, n))
}
